constexpr char32_t hangul_s = 0xAC00, hangul_l = 0x1100, hangul_v = 0x1161, hangul_t = 0x11A7;
constexpr char32_t hangul_l_count = 19, hangul_v_count = 21, hangul_t_count = 28;

char32_t compose(char32_t a, char32_t b) {
  if (a >= hangul_l && a < hangul_l + hangul_l_count && b >= hangul_v && b < hangul_v + hangul_v_count) {
    return hangul_s + ((a - hangul_l) * hangul_v_count + (b - hangul_v)) * hangul_t_count;
  }
  if (a >= hangul_s && a < hangul_s + 11172 && (a - hangul_s) % hangul_t_count == 0 && b > hangul_t &&
      b < hangul_t + hangul_t_count) {
    return a + (b - hangul_t);
  }
  if (a > 0xFFFF || b > 0xFFFF) return 0;
  const std::uint32_t key = (static_cast<std::uint32_t>(a) << 16) | static_cast<std::uint32_t>(b);
  const auto* it = std::lower_bound(std::begin(compositions), std::end(compositions), key,
                                    [](const Composition& c, std::uint32_t k) { return c.pair < k; });
  return it != std::end(compositions) && it->pair == key ? it->composed : 0;
}

