std::string name_to_utf8(std::u16string_view name) {
  std::u32string text;
  text.reserve(name.size());
  for (std::size_t i = 0; i < name.size(); ++i) {
    char32_t c = name[i];
    if (c >= 0xD800 && c < 0xDC00 && i + 1 < name.size() && name[i + 1] >= 0xDC00 && name[i + 1] < 0xE000) {
      c = 0x10000 + ((c - 0xD800) << 10) + (static_cast<char32_t>(name[i + 1]) - 0xDC00);
      ++i;
    } else if (c >= 0xD800 && c < 0xE000) {
      c = util::replacement_character;
    }
    if (c == '/') c = ':';  // the POSIX view of a name that contains '/'
    // Compose with the previous character when the pair has a composition.
    if (!text.empty()) {
      if (const char32_t composed = compose(text.back(), c); composed != 0) {
        text.back() = composed;
        continue;
      }
    }
    text.push_back(c);
  }
  return util::utf32_to_utf8(text);
}

